"""Milestone 1 storage: files on the server's disk under STORAGE_DIR/<user_id>/<random id>."""

import asyncio
import contextlib
from collections.abc import AsyncIterator
from pathlib import Path

from app.core.config import get_settings

CHUNK_SIZE = 1024 * 1024  # 1 MB


class LocalStorage:
    def __init__(self, root: str | Path) -> None:
        self.root = Path(root).resolve()

    def _path(self, key: str) -> Path:
        path = (self.root / key).resolve()
        # Keys are generated by the server, but double-check nothing escapes the storage folder.
        if self.root not in path.parents:
            raise ValueError("Invalid storage key")
        return path

    async def save(self, key: str, source: Path) -> None:
        target = self._path(key)
        await asyncio.to_thread(target.parent.mkdir, parents=True, exist_ok=True)
        # Same disk, so this is an instant rename rather than a copy.
        await asyncio.to_thread(source.replace, target)

    async def open(self, key: str) -> AsyncIterator[bytes]:
        path = self._path(key)
        with path.open("rb") as handle:  # noqa: ASYNC230 – reads happen in a worker thread below
            while chunk := await asyncio.to_thread(handle.read, CHUNK_SIZE):
                yield chunk

    async def delete(self, key: str) -> None:
        with contextlib.suppress(FileNotFoundError):
            await asyncio.to_thread(self._path(key).unlink)

    def temp_path(self, name: str) -> Path:
        """Where uploads are written while they are still being checked."""
        tmp = self.root / "tmp"
        tmp.mkdir(parents=True, exist_ok=True)
        return tmp / name


def get_storage() -> LocalStorage:
    """FastAPI dependency. In Milestone 2 this returns the encrypted S3 storage instead."""
    return LocalStorage(get_settings().storage_dir)
